 "content": "def transform(grid):
    h, w = len(grid), max(map(len, grid))
    src = [row[:] + [0] * (w - len(row)) for row in grid]
    out = [row[:] for row in src]
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if src[r-1][c] == src[r+1][c] == src[r][c-1] == src[r][c+1] == 3:
                centers.append((r, c, src[r][c]))
    for r, c, color in centers:
        for x in range(w):
            if src[r][x] != 3:
                out[r][x] = color
    for r, c, color in centers:
        for y in range(h):
            if src[y][c] != 3:
                out[y][c] = color
    # If another plus arm occurs in a projected row/column, it blocks the
    # ray in that direction, preserving the unpainted region beyond it.
    for r, c, color in centers:
        for step in (-1, 1):
            x = c + step
            while 0 <= x < w:
                if src[r][x] == 3:
                    for xx in range(x + step, 0 if step < 0 else w, step):
                        if src[r][xx] != 3:
