                    break
                x += step
            y = r + step
            while 0 <= y < h:
                if src[y][c] == 3:
                    for yy in range(y + step, 0 if step < 0 else h, step):
                        if src[yy][c] != 3:
                            out[yy][c] = 0
                    break
                y += step
    return out

