            if src[r][x] != 3:
                out[r][x] = color
        for y in range(h):
            if src[y][c] != 3:
                out[y][c] = color
    # The neutral cross makes a zero-valued interruption wherever projected
    # lines meet its row or column, while its own gray markers stay intact.
    for r, c, color in centers:
        if color == 0:
            for x in range(w):
                if src[r][x] == 0:
                    out[r][x] = 0
            for y in range(h):
                if src[y][c] == 0:
                    out[y][c] = 0
    return out",
